describe('File Upload and Organization', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should successfully upload a file and organize it into a folder', () => {
        const fileName = 'test-file.txt';
        const folderName = 'Test Folder';

        // Create a folder
        cy.get('[data-cy=create-folder-input]').type(folderName);
        cy.get('[data-cy=create-folder-button]').click();

        // Upload a file
        cy.get('[data-cy=file-upload-input]').attachFile(fileName);
        cy.get('[data-cy=upload-button]').click();

        // Verify the file is in the correct folder
        cy.get('[data-cy=folder]').contains(folderName).click();
        cy.get('[data-cy=file-list]').should('contain', fileName);
    });

    it('should show an error when trying to upload a file without selecting a folder', () => {
        const fileName = 'test-file.txt';

        // Attempt to upload a file without creating/selecting a folder
        cy.get('[data-cy=file-upload-input]').attachFile(fileName);
        cy.get('[data-cy=upload-button]').click();

        // Verify the error message
        cy.get('[data-cy=error-message]').should('be.visible').and('contain', 'Please select a folder before uploading.');
    });
});
